      fill(2, "희곡에서 인물의 행동, 표정, 무대 장치를 지시하는 글을 {{1}}이라고 합니다.", [["지문"]], "무대 지시라고도 합니다.", hint="'땅 지(地)'가 들어갑니다."),
      fill(3, "시나리오에서 장면 번호를 나타내는 기호는 {{1}}입니다.", [["S#"]], "Scene Number의 줄임입니다.", hint="Scene의 머리글자와 기호입니다."),
